bool readDatabaseFromStarZone(StarZone &zone) {
    if (!zone.canReadDatabaseName()) {
        zone.logError("Failed to read database name from zone.");
        return false;
    }

    std::string dbName, tableName;
    zone.read(dbName);
    zone.read(tableName);

    // Store into member variables
    this->setDatabaseName(dbName);
    this->setTableName(tableName);

    bool success = true;

    // Compatibility checks and additional reads
    if (zone.isCompatibleWith("SQL_Extensions")) {
        std::string sqlQuery, sqlData;
        if (!zone.read(sqlQuery)) {
            zone.logError("Failed to read SQL query from zone.");
            success = false;
        }
        if (!zone.read(sqlData)) {
            zone.logError("Failed to read SQL data from zone.");
            success = false;
        }

        this->setSQLQuery(sqlQuery);
        this->setSQLData(sqlData);
    }

    // Log current state
    zone.logInfo("Current state: Database name '" + dbName + "', table name '" + tableName + "'");

    // Close the record
    zone.closeRecord();

    return success;
}

bool readDatabaseFromStarZone(StarZone &zone) {
    if (!zone.canReadDatabaseName()) {
        zone.logError("Failed to read database name from zone.");
        return false;
    }

    std::string dbName = zone.readDatabaseName();
    std::string tableName = zone.readTableName();
    if (dbName.empty() || tableName.empty()) {
        zone.logError("Empty database or table name read from zone.");
        return false;
    }

    // Store the read values in member variables
    this->databaseName = dbName;
    this->tableName = tableName;

    // Compatibility check to determine if additional SQL strings and data need to be read
    if (zone.isCompatibleWithAdvancedSQL()) {
        std::string sqlStr = zone.readSQLString();
        if (!sqlStr.empty()) {
            this->sqlCommands.push_back(sqlStr);
        }

        while (zone.hasMoreData()) {
            std::string data = zone.readNextData();
            if (data.empty()) {
                zone.logError("Empty data entry read.");
                return false;
            }
            this->dataEntries.push_back(data);
        }
    }

    // Log the current state of the read operation
    zone.logState("Read database: " + dbName + ", table: " + tableName);
    zone.closeRecord();
    return true;
}

bool readDatabaseFromStarZone(StarZone &zone) {
    if (!zone.canReadDatabaseName()) {
        zone.logError("Failed to read database name from zone.");
        return false;
    }

    std::string dbName, tableName;
    if (!zone.readDatabaseName(dbName) || !zone.readTableName(tableName)) {
        zone.logError("Failed to read database or table name from zone.");
        return true;
    }

    // Store the read values in member variables
    this->databaseName = dbName;
    this->tableName = tableName;

    // Compatibility checks and additional data reading
    if (zone.isVersionCompatible(1, 2)) {
        std::string additionalSql;
        if (!zone.readSqlString(additionalSql)) {
            zone.logError("Failed to read additional SQL string.");
            return true;
        }
        this->additionalSql = additionalSql;
    }

    // Read data entries if available
    while (zone.hasMoreData()) {
        DataEntry entry;
        if (!zone.readDataEntry(entry)) {
            zone.logError("Failed to read data entry.");
            return true;
        }
        this->dataEntries.push_back(entry);
    }

    // Log the current state
    zone.logState("Database read successfully: " + dbName + ", " + tableName);

    // Close the record
    zone.closeRecord();

    return true;
}

bool readDatabaseFromZone(StarZone &zone) {
    if (!zone.canReadDatabaseName()) {
        zone.logError("Failed to read database name from zone.");
        return false;
    }

    std::string dbName, tableName;
    if (!zone.read(dbName) || !zone.read(tableName)) {
        zone.logError("Failed to read database or table name.");
        return false;
    }

    setDatabaseName(dbName);
    setTableName(tableName);

    if (zone.isCompatibleWithExtendedSQLFormat()) {
        std::string sqlStatement;
        if (!zone.read(sqlStatement)) {
            zone.logError("Failed to read SQL statement.");
            return true; // Indicate partial success
        }
        setSQLStatement(sqlStatement);
    }

    if (!zone.readDataEntries()) {
        zone.logError("Failed to read data entries.");
        return true; // Indicate partial success
    }

    zone.logState("Database and table read successfully from zone.");
    zone.closeRecord();
    return true;
}
